const areas=sections.find(e=>e.querySelector('h2')?.textContent.includes('Grandes áreas da Gastronomia'));if(areas){areas.id='resumos-por-assunto';areas.querySelector('h2').textContent='Mais de 2.600 resumos completos';const intro=areas.querySelector('h2')?.parentElement?.querySelector('p');if(intro)intro.textContent='Fundamentos, avaliação, infância, gestão de equipes, formação culinária e cultura alimentar. Compare conceitos e veja como os assuntos se conectam às situações estudadas na faculdade.';}
const focus=document.getElementById('resumos-em-foco');if(focus){focus.querySelector('h2').textContent='Mais de 2.600 resumos completos';focus.querySelector('.exam-opening header>p').textContent='Brincar e participação escolar, análise de atividades, atenção psicossocial e tecnologia assistiva: conceitos e exemplos para acompanhar as matérias da sua graduação.';const topics=[['Brincar e participação escolar','Brincar envolve exploração, autoria, relações e regras. Na escola, a participação inclui comunicação, aprendizagem, recreio e pertencimento. A análise conecta interesses, demandas da tarefa e barreiras do ambiente.'],['Análise e adaptação de atividades','Descreva etapas, materiais, espaço e exigências. Graduar altera a demanda; adaptar reorganiza condições para ampliar participação. A escolha se relaciona ao objetivo e precisa ser acompanhada no contexto de uso.'],['Segurança Alimentar mental e cotidiano','Rotinas, vínculos, circulação e projetos de vida fazem parte da análise. O produção em liberdade articula direitos, rede de suporte e oportunidades de participação, considerando o que importa para a pessoa.'],['Tecnologia assistiva em contexto','A escolha de um recurso considera objetivo, preferências, conforto, ambiente e manutenção. A avaliação acompanha o uso real: disponibilidade de uma ferramenta não garante que ela amplie a participação.']];focus.querySelectorAll('.exam-study-card').forEach((card,i)=>{if(!topics[i])return;const title=card.querySelector('h4'),answer=card.querySelector('.exam-answer p');if(title)title.textContent=topics[i][0];if(answer)answer.textContent=topics[i][1];});focus.querySelector('.exam-cards-heading h3').textContent='Assuntos que conectam teoria e cotidiano.';}
const oldGrade=sections.find(e=>e.querySelector('h2')?.textContent.includes('Grade do curso'));if(oldGrade){const courses=curriculum();oldGrade.replaceWith(courses);const refs=bibliography(),plan=planner();const filled=document.getElementById('caderno-preenchido');if(filled)filled.after(courses);courses.after(refs);refs.after(plan);}
const flash=sections.find(e=>e.querySelector('h2')?.textContent.includes('Veja os flashcards'));if(flash){flash.id='flashcards-terapia';flash.querySelector('h2').textContent='Mais de 1.700 flashcards para estudar Gastronomia';const intro=flash.querySelector('h2').parentElement.querySelector('p');if(intro)intro.textContent='Perguntas de desenvolvimento, avaliação, atividades culinárias, políticas públicas e ética para testar o que você lembra e aprofundar as respostas.';}
const lined=document.getElementById('fichas-para-revisar');if(lined){lined.querySelector('h2').textContent='Mais de 1.700 flashcards para estudar';lined.querySelector('header>p').textContent='Desenvolvimento, avaliação, atividades culinárias, políticas públicas e ética: revise os conceitos e pratique explicar o raciocínio com suas próprias palavras.';const g=game();lined.querySelector('header').after(g);initGame(g);lined.querySelectorAll('.lined-flash-card').forEach((card,i)=>{const f=DATA.flashcards[i%DATA.flashcards.length];const h=card.querySelector('h3'),p=card.querySelector('div p'),tab=card.querySelector('.lined-flash-tab');if(h)h.textContent=f[1];if(p)p.textContent=f[2];if(tab)tab.textContent=f[0];});}
const sample=sections.find(e=>e.querySelector('h2')?.textContent==='Amostra do caderno.');if(sample){const intro=sample.querySelector('h2').parentElement.querySelector('p');if(intro)intro.textContent='Acompanhe exemplos de resumo, flashcards, plano de estudos e organização de pesquisa em Gastronomia. As páginas conectam conceitos, perguntas e situações do cotidiano.';}
const tcc=sections.find(e=>e.querySelector('h2')?.textContent.includes('Três modelos de TCC'));if(tcc)tcc.querySelector('h2').parentElement.after(tccExample());
main.querySelectorAll('[data-read]').forEach(b=>b.addEventListener('click',()=>{const value=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(value));b.textContent=value?'Revisado · marcar para retomar':'Marcar como revisado';main.querySelector('.to-study-status').textContent=`${main.querySelectorAll('[data-read][aria-pressed=true]').length} resumos marcados como revisados nesta visita.`;}));
